css:
.topteam-sim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    background: linear-gradient(160deg, #0e1726 0%, #141f33 55%, #0b1422 100%);
    color: #d8dee9;
    padding: 28px;
    border-radius: 14px;
    max-width: 1080px;
    margin: 0 auto;
    box-shadow: 0 18px 48px rgba(0,0,0,0.45);
    border: 1px solid rgba(197,164,92,0.18);
}

.topteam-sim-header {
    text-align: center;
    border-bottom: 1px solid rgba(197,164,92,0.25);
    padding-bottom: 18px;
    margin-bottom: 22px;
}

.topteam-sim-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: #c5a45c;
    background: rgba(197,164,92,0.10);
    border: 1px solid rgba(197,164,92,0.35);
    padding: 4px 14px;
    border-radius: 999px;
    margin-bottom: 12px;
}

.topteam-sim-header h1 {
    font-size: 2rem;
    font-weight: 700;
    color: #f4f6fb;
    margin: 6px 0 8px;
    letter-spacing: 0.01em;
}

.topteam-sim-subtitle {
    font-size: 0.96rem;
    color: #9aa7bd;
    max-width: 760px;
    margin: 0 auto;
    line-height: 1.5;
}

.topteam-sim-period-counter {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
    justify-content: center;
    font-size: 0.95rem;
    color: #b8c2d6;
    background: rgba(255,255,255,0.03);
    border: 1px solid rgba(255,255,255,0.06);
    border-radius: 10px;
    padding: 10px 16px;
    margin-bottom: 22px;
}

.topteam-sim-period-counter #currentDay,
.topteam-sim-period-counter #maxPeriods {
    font-weight: 700;
    color: #c5a45c;
}

.topteam-sim-round-name {
    font-weight: 700;
    color: #f4f6fb;
    margin-left: 6px;
    padding-left: 10px;
    border-left: 1px solid rgba(197,164,92,0.4);
}

.topteam-sim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    color: #8290a8;
    font-style: italic;
}

.topteam-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 24px;
}

.topteam-sim-status-card {
    background: linear-gradient(150deg, #18233a 0%, #121b2c 100%);
    border: 1px solid rgba(255,255,255,0.07);
    border-radius: 12px;
    padding: 18px 16px;
    text-align: center;
    transition: transform 0.15s ease, border-color 0.15s ease;
}

.topteam-sim-status-card:hover {
    transform: translateY(-2px);
    border-color: rgba(197,164,92,0.4);
}

.topteam-sim-status-card.topteam-sim-card-primary {
    border-color: rgba(197,164,92,0.55);
    box-shadow: inset 0 0 22px rgba(197,164,92,0.08);
}

.topteam-sim-status-card.topteam-sim-card-risk {
    border-color: rgba(224,108,108,0.4);
}

.topteam-sim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: #8e9bb3;
    margin-bottom: 8px;
}

.topteam-sim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1;
    color: #f4f6fb;
}

.topteam-sim-card-primary .topteam-sim-value {
    color: #d9b974;
}

.topteam-sim-card-risk .topteam-sim-value {
    color: #e88a8a;
}

.topteam-sim-sublabel {
    font-size: 0.72rem;
    color: #75829a;
    margin-top: 8px;
    line-height: 1.3;
}

.topteam-sim-briefing {
    display: flex;
    gap: 16px;
    align-items: flex-start;
    background: rgba(197,164,92,0.06);
    border: 1px solid rgba(197,164,92,0.28);
    border-left: 4px solid #c5a45c;
    border-radius: 10px;
    padding: 18px 20px;
    margin-bottom: 22px;
}

.topteam-sim-briefing-icon {
    font-size: 1.6rem;
    line-height: 1;
}

.topteam-sim-briefing-title {
    font-size: 1.08rem;
    font-weight: 700;
    color: #f4f6fb;
    margin-bottom: 8px;
}

.topteam-sim-briefing-text {
    font-size: 0.92rem;
    color: #b8c2d6;
    line-height: 1.6;
}

.topteam-sim-briefing-text strong {
    color: #d9b974;
}

.topteam-sim-controls {
    background: rgba(255,255,255,0.025);
    border: 1px solid rgba(255,255,255,0.06);
    border-radius: 12px;
    padding: 22px 24px;
    margin-bottom: 22px;
}

.topteam-sim-controls h3 {
    font-size: 1.12rem;
    font-weight: 700;
    color: #f4f6fb;
    margin: 0 0 16px;
    padding-bottom: 10px;
    border-bottom: 1px solid rgba(255,255,255,0.07);
}

.topteam-sim-panel label {
    display: block;
    font-size: 0.9rem;
    font-weight: 600;
    color: #cdd6e6;
    margin: 16px 0 7px;
    line-height: 1.4;
}

.topteam-sim-panel label:first-child {
    margin-top: 0;
}

.topteam-sim-container select,
.topteam-sim-container input[type="number"] {
    width: 100%;
    background-color: #0d1626;
    color: #eef2f9;
    border: 1px solid rgba(197,164,92,0.35);
    border-radius: 8px;
    padding: 11px 13px;
    font-size: 0.9rem;
    transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.topteam-sim-container select:focus,
.topteam-sim-container input[type="number"]:focus {
    outline: none;
    border-color: #c5a45c;
    box-shadow: 0 0 0 3px rgba(197,164,92,0.18);
}

.topteam-sim-container select option {
    background-color: #0d1626;
    color: #eef2f9;
}

.topteam-sim-container input[type="range"] {
    width: 100%;
    margin: 6px 0 0;
    accent-color: #c5a45c;
    background: transparent;
    cursor: pointer;
}

.topteam-sim-range-readout {
    font-size: 0.85rem;
    color: #9aa7bd;
    margin-top: 6px;
}

.topteam-sim-range-readout span:last-child {
    font-weight: 700;
    color: #d9b974;
}

.topteam-sim-container .btn-primary {
    background: linear-gradient(135deg, #c5a45c 0%, #a8893f 100%);
    border: none;
    color: #14110a;
    font-weight: 700;
    letter-spacing: 0.02em;
    padding: 12px 26px;
    border-radius: 8px;
    margin-top: 22px;
    box-shadow: 0 6px 18px rgba(197,164,92,0.25);
    transition: transform 0.12s ease, box-shadow 0.12s ease;
}

.topteam-sim-container .btn-primary:hover {
    transform: translateY(-1px);
    box-shadow: 0 8px 22px rgba(197,164,92,0.38);
    color: #14110a;
}

.topteam-sim-container .btn-outline-secondary {
    margin-top: 22px;
    margin-left: 10px;
    color: #9aa7bd;
    border-color: rgba(255,255,255,0.18);
}

.topteam-sim-container .btn-outline-secondary:hover {
    background: rgba(255,255,255,0.06);
    color: #d8dee9;
}

.topteam-sim-coach {
    background: linear-gradient(150deg, #11203a 0%, #0d182b 100%);
    border: 1px solid rgba(90,140,210,0.28);
    border-left: 4px solid #5a8cd2;
    border-radius: 10px;
    padding: 18px 20px;
    margin-bottom: 22px;
}

.topteam-sim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #7fa8e0;
    font-weight: 700;
    margin-bottom: 8px;
}

.topteam-sim-coach-body {
    font-size: 0.92rem;
    color: #c2d0e6;
    line-height: 1.6;
}

.topteam-sim-coach-body strong {
    color: #aac6ee;
}

.topteam-sim-history,
.topteam-sim-chart {
    background: rgba(255,255,255,0.025);
    border: 1px solid rgba(255,255,255,0.06);
    border-radius: 12px;
    padding: 20px 22px;
    margin-bottom: 22px;
}

.topteam-sim-history h3,
.topteam-sim-chart h3 {
    font-size: 1.05rem;
    font-weight: 700;
    color: #f4f6fb;
    margin: 0 0 14px;
}

.topteam-sim-container table.table {
    color: #c2cbdc;
    margin-bottom: 0;
}

.topteam-sim-container table.table th {
    color: #c5a45c;
    border-color: rgba(255,255,255,0.1);
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.topteam-sim-container table.table td {
    border-color: rgba(255,255,255,0.06);
    font-size: 0.88rem;
    vertical-align: middle;
}

.topteam-sim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .topteam-sim-container {
        padding: 18px;
    }
    .topteam-sim-header h1 {
        font-size: 1.5rem;
    }
    .topteam-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .topteam-sim-value {
        font-size: 2rem;
    }
    .topteam-sim-period-counter {
        font-size: 0.85rem;
    }
    .topteam-sim-clock {
        margin-left: 0;
        width: 100%;
        text-align: center;
    }
    .topteam-sim-briefing {
        flex-direction: column;
        gap: 8px;
    }
    .topteam-sim-container .btn-outline-secondary {
        margin-left: 0;
        display: block;
    }
}


/* FIX v1.1.0 — completion / board-debrief screen */
.att-completion { padding: 10px 6px; text-align: center; }
.att-completion-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #64748b; margin-bottom: 6px; }
.att-completion-verdict { font-size: 20px; font-weight: 700; color: #0f172a; margin-bottom: 8px; }
.att-completion-score { font-size: 16px; color: #0f172a; margin-bottom: 14px; }
.att-completion-score strong { color: #4f46e5; }
.att-completion-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.att-completion-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 8px 12px; background: #f1f5f9; border-radius: 8px; min-width: 100px; }
.att-completion-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #64748b; }
.att-completion-metric strong { font-size: 16px; color: #0f172a; }
.att-completion-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 680px; text-align: left; }
.att-completion-insights li { padding: 9px 13px; margin-bottom: 7px; background: #eef2ff; border-left: 3px solid #4f46e5; border-radius: 4px; color: #1e293b; font-size: 13px; }

js:
(function() {
    'use strict';

    class TopTeamAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Aligning the Top Team`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // The concept's truth: the Infrastructure President's resistance is IDENTITY, not arithmetic;
            // the "yes" is surface compliance; the founder is still psychologically in the room.
            this.TRUE_DRIVER = `identity`;
            this.TRUE_YES = `surface`;
            this.FOUNDER_RIGHT = `bring`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    alignment: 38,        // genuine alignment (not performed)
                    momentum: 30,         // transformation momentum toward 3% -> 9%
                    board: 60,            // board confidence under the 2-quarter clock
                    risk: 45,             // derailment risk (fracture + talent flight)
                    compliance: 0,        // hidden: alignment "bought" by fear rather than genuine
                    talentRetained: true, // do the 2 cloud leaders stay?
                    diagnosedRight: false,
                    capitalBlewUp: false,
                    chairAlienated: false,
                    alignHistory: [38],
                    boardHistory: [60],
                    riskHistory: [45],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    driver: `identity`,
                    yes: `surface`,
                    founder: `bring`,
                    depth: 65,
                    mechanism: `cocreate`,
                    contain: 45,
                    chair: `private`,
                    talent: `signal`,
                    first: `align`,
                    win: `cloudwin`,
                    capital: `afteralign`,
                    pace: 50,
                    frame: `honest`,
                    probe: `invite`,
                    roadmap: `milestones`,
                    boardContain: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);
            const num = (id) => { const el = document.getElementById(id); return el ? parseInt(el.value, 10) : NaN; };
            const sel = (id) => { const el = document.getElementById(id); return el ? el.value : null; };

            if (round === 1) {
                let v;
                if ((v = sel(`driverInput`)) !== null) decisions.driver = v;
                if ((v = sel(`yesInput`)) !== null) decisions.yes = v;
                if ((v = sel(`founderInput`)) !== null) decisions.founder = v;
                decisions.depth = num(`depthInput`);
                if (!Number.isFinite(decisions.depth) || decisions.depth < 0 || decisions.depth > 100) { warn(`warn_depth_range`); return false; }
            } else if (round === 2) {
                let v;
                if ((v = sel(`mechanismInput`)) !== null) decisions.mechanism = v;
                if ((v = sel(`chairInput`)) !== null) decisions.chair = v;
                if ((v = sel(`talentInput`)) !== null) decisions.talent = v;
                decisions.contain = num(`containInput`);
                if (!Number.isFinite(decisions.contain) || decisions.contain < 0 || decisions.contain > 100) { warn(`warn_contain_range`); return false; }
            } else if (round === 3) {
                let v;
                if ((v = sel(`firstInput`)) !== null) decisions.first = v;
                if ((v = sel(`winInput`)) !== null) decisions.win = v;
                if ((v = sel(`capitalInput`)) !== null) decisions.capital = v;
                decisions.pace = num(`paceInput`);
                if (!Number.isFinite(decisions.pace) || decisions.pace < 0 || decisions.pace > 100) { warn(`warn_pace_range`); return false; }
            } else if (round === 4) {
                let v;
                if ((v = sel(`frameInput`)) !== null) decisions.frame = v;
                if ((v = sel(`probeInput`)) !== null) decisions.probe = v;
                if ((v = sel(`roadmapInput`)) !== null) decisions.roadmap = v;
                decisions.boardContain = num(`boardContainInput`);
                if (!Number.isFinite(decisions.boardContain) || decisions.boardContain < 0 || decisions.boardContain > 100) { warn(`warn_contain_range`); return false; }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let alignD = 0, momD = 0, boardD = 0, riskD = 0, compD = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // READ THE ROOM. Diagnosing identity (not capital) and surface-yes (not real alignment)
                // is what makes everything downstream possible. Founder shadow must be treated as live.
                if (d.driver === this.TRUE_DRIVER) {
                    alignD += 8; riskD -= 6; ds.diagnosedRight = true; coachKey = `coach_r1_identity`;
                } else if (d.driver === `capital`) {
                    alignD -= 4; riskD += 6; coachKey = `coach_r1_capital`;   // Common Error 2: a debate to be won
                } else if (d.driver === `power`) {
                    alignD -= 2; riskD += 3; coachKey = `coach_r1_power`;
                } else { // incompetence
                    alignD -= 6; riskD += 8; coachKey = `coach_r1_incompetence`;
                }

                if (d.yes === this.TRUE_YES) {
                    alignD += 6; riskD -= 6;
                } else if (d.yes === `aligned`) {
                    // Common Error 1: taking "yes" at face value
                    alignD -= 8; riskD += 12; momD += 4; coachKey = `coach_r1_facevalue`;
                } else { // majority
                    alignD -= 4; riskD += 8; coachKey = `coach_r1_majority`;
                }

                if (d.founder === this.FOUNDER_RIGHT) {
                    boardD += 6; riskD -= 4;
                } else if (d.founder === `around`) {
                    boardD -= 5; riskD += 6; ds.chairAlienated = true;
                } else { // ignore
                    boardD -= 10; riskD += 10; ds.chairAlienated = true; coachKey = `coach_r1_founder`;
                }

                // Diagnostic depth: too shallow blinds you; extreme over-analysis stalls (board clock).
                if (d.depth >= 55 && d.depth <= 85) { alignD += 5; riskD -= 4; }
                else if (d.depth < 35) { alignD -= 6; riskD += 6; }      // acting on the surface read
                else if (d.depth > 90) { momD -= 4; boardD -= 3; }       // paralysis by analysis

                summaryKey = (ds.diagnosedRight && d.yes === this.TRUE_YES) ? `sum_r1_good` : `sum_r1_weak`;

            } else if (round === 2) {
                // CHOOSE THE ALIGNING MECHANISM. Co-create / burning-platform / off-site build GENUINE
                // alignment; removing the loudest skeptic buys visible compliance and terrifies the team.
                const diagBonus = ds.diagnosedRight ? 1.0 : 0.55; // a mechanism chosen on a wrong diagnosis is half-blind
                switch (d.mechanism) {
                    case `cocreate`:
                        alignD += 18; momD += 8; riskD -= 8; coachKey = `coach_r2_cocreate`; break;
                    case `burning`:
                        alignD += 13; momD += 10; riskD -= 4; coachKey = `coach_r2_burning`; break;
                    case `offsite`:
                        alignD += 12; riskD -= 6; coachKey = `coach_r2_offsite`; break;
                    case `incentives`:
                        alignD += 6; momD += 6; riskD += 2; coachKey = `coach_r2_incentives`; break;
                    case `remove`:
                        // Common Error 3 / Aligning by fear: visible alignment, hidden terror, board alarmed.
                        alignD += 4; compD += 22; riskD += 14; boardD -= 12; coachKey = `coach_r2_remove`; break;
                }
                if (d.mechanism !== `remove`) {
                    alignD = Math.round(alignD * diagBonus);
                    if (!ds.diagnosedRight) coachKey = `coach_r2_blind`;
                }

                // Containment vs. confrontation. The concept: contain anxiety, don't avoid OR force.
                const force = d.contain;
                if (force >= 35 && force <= 60) { alignD += 6; riskD -= 5; }   // deliberate containment
                else if (force < 20) { alignD -= 5; momD -= 5; riskD += 3; coachKey = `coach_r2_avoid`; } // avoidance dressed as patience
                else if (force > 80) { alignD -= 8; riskD += 10; compD += 8; coachKey = `coach_r2_force`; } // forcing => compliance

                // The founder-chair handling carries through the board interface.
                if (d.chair === `private`) { boardD += 8; riskD -= 4; }
                else if (d.chair === `inform`) { boardD += 1; }
                else { boardD -= 8; riskD += 6; ds.chairAlienated = true; } // bypass

                // Talent: showing alignment (not cash) is what keeps the cloud leaders — IF alignment is real.
                if (d.talent === `signal`) {
                    if (ds.alignment + alignD >= 50) { momD += 8; riskD -= 8; ds.talentRetained = true; }
                    else { riskD += 4; ds.talentRetained = false; coachKey = (coachKey === `coach_default`) ? `coach_r2_talent_empty` : coachKey; }
                } else if (d.talent === `retention`) {
                    momD += 3; riskD -= 2; // money slows the bleed but doesn't fix the cause
                } else { // wait
                    riskD += 10; ds.talentRetained = false; coachKey = (coachKey === `coach_default`) ? `coach_r2_talent_wait` : coachKey;
                }

                summaryKey = (d.mechanism === `cocreate` || d.mechanism === `burning`) ? `sum_r2_good` : (d.mechanism === `remove` ? `sum_r2_fear` : `sum_r2_weak`);

            } else if (round === 3) {
                // SEQUENCE. Order matters as much as the moves. Capital-first before alignment fractures
                // the team; alignment-first under the clock needs an early win to keep the board.
                const aligned = ds.alignment >= 52;

                if (d.first === `align`) {
                    if (aligned) { alignD += 6; momD += 4; }
                    else { alignD += 12; riskD -= 6; } // still the right first move even if not yet there
                    coachKey = `coach_r3_alignfirst`;
                } else if (d.first === `win`) {
                    momD += 12; boardD += 8;
                    if (!aligned) { riskD += 8; coachKey = `coach_r3_winearly`; } // exposes the divide
                    else { riskD -= 2; coachKey = `coach_r3_win_ok`; }
                } else if (d.first === `capital`) {
                    // Common Error 4: leading with capital reallocation before alignment.
                    momD += 6;
                    if (!aligned) {
                        alignD -= 16; riskD += 20; boardD -= 6; ds.capitalBlewUp = true; coachKey = `coach_r3_capitalfirst`;
                    } else {
                        alignD -= 4; momD += 6; coachKey = `coach_r3_capital_ok`;
                    }
                } else { // chair first
                    boardD += 12; riskD -= 4; momD -= 2; coachKey = `coach_r3_chairfirst`;
                }

                // The early win. A non-threatening cloud win or a jointly-owned KPI builds momentum
                // without arming the skeptics; a headline capex shift or layoffs hand them ammunition.
                switch (d.win) {
                    case `cloudwin`:
                        momD += 12; boardD += 8; riskD -= 4; break;
                    case `jointkpi`:
                        momD += 8; alignD += 8; riskD -= 6; break;
                    case `bigcapex`:
                        momD += 6; alignD -= 10; riskD += 12; if (!ds.capitalBlewUp) ds.capitalBlewUp = true; break;
                    case `layoffs`:
                        momD += 4; alignD -= 12; riskD += 14; boardD -= 4; break;
                }

                // When to touch the SGD 180M. After alignment is the durable answer.
                if (d.capital === `afteralign`) {
                    if (aligned) { momD += 8; riskD -= 4; } else { momD += 2; }
                } else if (d.capital === `phased`) {
                    momD += 5; riskD += 2;
                } else { // now
                    momD += 8;
                    if (!aligned) { alignD -= 10; riskD += 12; boardD -= 4; ds.capitalBlewUp = true; }
                }

                // Pacing under the clock. Balanced wins; too slow loses the board; too fast fractures.
                if (d.pace >= 40 && d.pace <= 65) { boardD += 5; momD += 4; }
                else if (d.pace < 25) { boardD -= 10; coachKey = `coach_r3_tooslow`; }
                else if (d.pace > 80) { alignD -= 6; riskD += 8; coachKey = `coach_r3_toofast`; }

                summaryKey = ((d.first === `align` || d.first === `chair`) && (d.win === `cloudwin` || d.win === `jointkpi`) && d.capital !== `now`) ? `sum_r3_good` : `sum_r3_weak`;

            } else if (round === 4) {
                // HOLD THE BOARD. The founder-chair probes for real alignment vs compliance.
                // Honest framing + inviting the President to speak demonstrates genuine alignment.
                if (d.frame === `honest`) { boardD += 12; riskD -= 6; }
                else if (d.frame === `triumph`) {
                    // Overclaiming invites the chair to find the gap. Worse if alignment is thin / compliant.
                    if (ds.compliance > 10 || ds.alignment < 55) { boardD -= 14; riskD += 10; coachKey = `coach_r4_triumph_caught`; }
                    else { boardD += 2; coachKey = `coach_r4_triumph`; }
                } else { // defensive
                    boardD -= 12; riskD += 6; coachKey = `coach_r4_defensive`;
                }

                if (d.probe === `invite`) {
                    // The real test: can the loudest skeptic speak FOR the transformation in his own words?
                    if (ds.alignment >= 58 && ds.compliance <= 10) { boardD += 16; alignD += 6; riskD -= 8; coachKey = `coach_r4_invite_real`; }
                    else { boardD -= 10; riskD += 8; coachKey = `coach_r4_invite_exposed`; } // exposes compliance live
                } else if (d.probe === `reassure`) {
                    boardD += 2; if (ds.compliance > 10) { boardD -= 6; }
                } else { // deflect
                    boardD -= 8; riskD += 4; coachKey = `coach_r4_deflect`;
                }

                if (d.roadmap === `milestones`) { boardD += 10; momD += 6; riskD -= 4; }
                else if (d.roadmap === `growth`) { boardD -= 4; riskD += 6; momD += 4; }
                else { boardD -= 8; riskD += 10; alignD -= 6; } // immediate restructure spooks everyone

                // Contain the board's anxiety as deliberately as the team's.
                const bc = d.boardContain;
                if (bc >= 50 && bc <= 80) { boardD += 8; }
                else if (bc < 30) { boardD -= 8; coachKey = (coachKey === `coach_default`) ? `coach_r4_nocontain` : coachKey; }
                else if (bc > 90) { boardD -= 3; } // over-reassurance reads as spin

                if (!ds.talentRetained) { momD -= 6; boardD -= 4; }
                if (ds.chairAlienated) { boardD -= 8; riskD += 6; }

                summaryKey = (d.frame === `honest` && d.probe === `invite` && d.roadmap === `milestones`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply deltas with clamps.
            ds.alignment = Math.max(0, Math.min(100, ds.alignment + alignD));
            ds.momentum = Math.max(0, Math.min(100, ds.momentum + momD));
            ds.board = Math.max(0, Math.min(100, ds.board + boardD));
            ds.risk = Math.max(0, Math.min(100, ds.risk + riskD));
            ds.compliance = Math.max(0, Math.min(100, ds.compliance + compD));

            ds.alignHistory.push(ds.alignment);
            ds.boardHistory.push(ds.board);
            ds.riskHistory.push(ds.risk);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 FIX A — expose the composite (clamped 0-100) on the reporting paths.
            var _c = Math.max(0, Math.min(100, Math.round(ds.alignment * 0.35 + ds.momentum * 0.2 + ds.board * 0.25 + (100 - ds.risk) * 0.2 - ds.compliance * 0.3)));
            ds.score = _c;
            ds.performance = { overallScore: _c };
            return {
                period: state.currentPeriod,
                score: _c,
                overallScore: _c,
                alignment: ds.alignment,
                alignDelta: alignD,
                momentum: ds.momentum,
                board: ds.board,
                boardDelta: boardD,
                risk: ds.risk,
                compliance: ds.compliance,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

