        formatCompletionMessage(summary) {
            var t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            var score = (summary.score != null) ? summary.score : 0;
            var grade = summary.gradeKey ? t(summary.gradeKey) : '';
            var insights = summary.insights || [];
            var items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            var metric = function (label, val) {
                return '<div class="att-completion-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            var metrics = ''
                + metric(t('comp_align_label'), (summary.alignment != null ? summary.alignment : '-'))
                + metric(t('comp_momentum_label'), (summary.momentum != null ? summary.momentum : '-'))
                + metric(t('comp_board_label'), (summary.board != null ? summary.board : '-'))
                + metric(t('comp_risk_label'), (summary.risk != null ? summary.risk : '-'))
                + metric(t('comp_compliance_label'), (summary.compliance != null ? summary.compliance : '-'));
            return ''
                + '<div class="att-completion">'
                +   '<div class="att-completion-heading">' + t('comp_heading') + '</div>'
                +   '<div class="att-completion-verdict">' + grade + '</div>'
                +   '<div class="att-completion-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="att-completion-metrics">' + metrics + '</div>'
                +   (items ? '<ul class="att-completion-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const align = ds.alignment, momentum = ds.momentum, board = ds.board, risk = ds.risk;

            // Genuine alignment requires real alignment AND low "compliance-by-fear" residue.
            const genuine = align >= 60 && ds.compliance <= 12;
            const boardHeld = board >= 55;
            const composite = Math.round(align * 0.35 + momentum * 0.2 + board * 0.25 + (100 - risk) * 0.2 - ds.compliance * 0.3);

            let performance = `Stalled Transformation`;
            if (genuine && boardHeld && composite >= 70) performance = `Aligned Journey`;
            else if (boardHeld && composite >= 56) performance = `Momentum Building`;
            else if (composite >= 42) performance = `Fragile Mandate`;

            const insights = [];
            if (genuine && boardHeld) insights.push(window.mySimulation.t(`insight_genuine`));
            else if (ds.compliance > 12) insights.push(window.mySimulation.t(`insight_compliance`));
            else if (!boardHeld) insights.push(window.mySimulation.t(`insight_boardlost`));
            else insights.push(window.mySimulation.t(`insight_stalled`));

            if (!ds.diagnosedRight) insights.push(window.mySimulation.t(`insight_misdiagnosed`));
            if (ds.capitalBlewUp) insights.push(window.mySimulation.t(`insight_capital`));
            if (ds.chairAlienated) insights.push(window.mySimulation.t(`insight_founder`));
            if (!ds.talentRetained) insights.push(window.mySimulation.t(`insight_talent`));
            if (risk >= 60) insights.push(window.mySimulation.t(`insight_risk`));

            const _sc = Math.max(0, Math.min(100, composite));
            const _gk = (genuine && boardHeld && composite >= 70) ? 'grade_aligned' : (boardHeld && composite >= 56) ? 'grade_momentum' : (composite >= 42) ? 'grade_fragile' : 'grade_stalled';
            if (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) {
                window.mySimulation.state.domainState.score = _sc;
                window.mySimulation.state.domainState.performance = { overallScore: _sc, grade: window.mySimulation.t(_gk) };
            }
            return {
                score: _sc,
                gradeKey: _gk,
                alignment: align,
                momentum: momentum,
                board: board,
                risk: risk,
                compliance: ds.compliance,
                composite: composite,
                performance: performance,
                genuine: genuine,
                boardHeld: boardHeld,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (!ds.diagnosedRight && state.currentPeriod >= 1 && state.currentPeriod < 4) return window.mySimulation.t(`hint_diagnose`);
